void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 p = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    float d = abs(fract(length(p) * 8.0) - 0.5);
    float w = fwidth(d);
    float a = smoothstep(0.0, w * 1.5, d - 0.1);
    fragColor = vec4(vec3(a), 1.0);
}
